parts.text:
{
  "extractions": [
    {
      "unit": "F001",
      "unit_attributes": {
        "statement": "A generator may accumulate as much as fifty-five gallons of non-acute hazardous waste and either one quart of liquid acute hazardous waste listed in rule 3745-51-31 or paragraph (E) of rule 3745-51-33 of the Administrative Code or one kilogram (kg) (2.2 pounds) of solid acute hazardous waste listed in rule 3745-51-31 or paragraph (E) of rule 3745-51-33 of the Administrative Code in containers at or near any point of generation where wastes initially accumulate which is under the control of the operator of the process generating the waste, without a permit or permit by rule and without complying with the requirements of Chapters 3745-50, 3745-54 to 3745-57 and 3745-205, 3745-65 to 3745-69 and 3745-256, 3745-266, and 3745-267 of the Administrative Code, provided that all of the conditions for exemption in this rule are met, and may comply with the conditions for exemption in this rule instead of complying with the conditions for exemption in paragraph (B) of rule 3745-52-16 or paragraph (A) of rule 3745-52-17 of the Administrative Code, except as required in paragraphs (A)(7) and (A)(8) of this rule.",
        "kind": "permission",
        "modality": "may",
        "modality_quote": "may",
        "references": [
          "3745-51-31",
          "3745-51-33(E)",
          "Chapters 3745-50",
          "3745-54 to 3745-57",
          "3745-205",
          "3745-65 to 3745-69",
          "3745-256",
          "3745-266",
          "3745-267",
          "3745-52-16(B)",
          "3745-52-17(A)",
          "paragraphs (A)(7) and (A)(8)"
        ]
      }
    },
    {
      "unit": "F002",
      "unit_attributes": {
        "statement": "As a condition for exemption for satellite accumulation under paragraph (A) of rule 3745-52-15, if a container holding hazardous waste is not in good condition, or if the container begins to leak, the generator shall immediately transfer the hazardous waste from this container to a container that is in good condition and does not leak, or immediately transfer and manage the waste in a central accumulation area operated in compliance with paragraph (B) of rule 3745-52-16 or paragraph (A) of rule 3745-52-17 of the Administrative Code.",
        "kind": "requirement",
        "modality": "must",
        "scope_text": "Applies as a condition for satellite accumulation exemption under paragraph (A) when a container holding hazardous waste is not in good condition, or if the container begins to leak.",
        "scope_quotes": [
          "F001",
          "F002"
        ],
        "modality_quote": "shall",
        "references": [
          "3745-52-16(B)",
          "3745-52-17(A)"
        ]
      }
    },
    {
      "unit": "F003",
      "unit_attributes": {
        "statement": "As a condition for exemption for satellite accumulation under paragraph (A) of rule 3745-52-15, the generator shall use a container made of or lined with materials that will not react with, and are otherwise compatible with, the hazardous waste to be accumulated, so that the ability of the container to contain the waste is not impaired.",
        "kind": "requirement",
        "modality": "must",
        "scope_text": "Governed by paragraph (A) as a condition for exemption for satellite accumulation of hazardous waste.",
        "scope_quotes": [
          "F001"
        ],
        "modality_quote": "shall"
      }
    },
    {
      "unit": "F005",
      "unit_attributes": {
        "statement": "As a condition for exemption for satellite accumulation under paragraph (A) of rule 3745-52-15, incompatible wastes, or incompatible wastes and materials, shall not be placed in the same container, unless paragraph (B) of rule 3745-65-17 of the Administrative Code is complied with (see appendix to rule 3745-66-99 of the Administrative Code for examples).",
        "kind": "prohibition",
        "modality": "must_not",
        "scope_text": "Governed by paragraph (A) as a condition for satellite accumulation exemption.",
        "scope_quotes": [
          "F001"
        ],
        "modality_quote": "shall not",
        "references": [
          "3745-66-99",
          "3745-65-17(B)"
        ]
      }
    },
    {
      "unit": "F006",
      "unit_attributes": {
        "statement": "As a condition for exemption for satellite accumulation under paragraph (A) of rule 3745-52-15, hazardous waste shall not be placed in an unwashed container that previously held an incompatible waste or material, unless paragraph (B) of rule 3745-65-17 of the Administrative Code is complied with (see appendix to rule 3745-66-99 of the Administrative Code for examples).",
        "kind": "prohibition",
        "modality": "must_not",
        "scope_text": "Governed by paragraph (A) as a condition for satellite accumulation exemption.",
        "scope_quotes": [
          "F001"
        ],
        "modality_quote": "shall not",
        "references": [
          "3745-66-99",
          "3745-65-17(B)"
        ]
      }
    },
    {
      "unit": "F007",
      "unit_attributes": {
        "statement": "As a condition for exemption for satellite accumulation under paragraph (A) of rule 3745-52-15, a container holding a hazardous waste that is incompatible with any waste or other materials accumulated nearby in other containers shall be separated from the other materials or protected from the incompatible waste or material by any practical means.",
        "kind": "requirement",
        "modality": "must",
        "scope_text": "Governed by paragraph (A) as a condition for satellite accumulation exemption.",
        "scope_quotes": [
          "F001"
        ],
        "modality_quote": "shall"
      }
    },
    {
      "unit": "F008:F012",
      "unit_attributes": {
        "statement": "As a condition for exemption for satellite accumulation under paragraph (A) of rule 3745-52-15, a container holding hazardous waste shall be closed at all times during accumulation, except when adding, removing, or consolidating waste, or when temporary venting of a container is necessary either for the proper operation of equipment or to prevent dangerous situations, such as build-up of extreme pressure.",
        "kind": "requirement",
        "modality": "must",
        "scope_text": "Governed by paragraph (A) as a condition for satellite accumulation exemption.",
        "scope_quotes": [
          "F001"
        ],
        "modality_quote": "shall",
        "choice_text": "The container must remain closed at all times except under either of two circumstances: (a) adding, removing, or consolidating waste; or (b) temporary venting necessary either (i) for proper equipment operation or (ii) to prevent dangerous situations like extreme pressure build-up.",
        "choice_quote": "F008:F012"
      }
    },
    {
      "unit": "F013:F015",
      "unit_attributes": {
        "statement": "As a condition for exemption for satellite accumulation under paragraph (A) of rule 3745-52-15, a generator shall mark or label the generator's container with both the words 'Hazardous Waste' and an indication of the hazards of the contents [examples include, but are not limited to, the applicable hazardous waste characteristics (i.e., ignitable, corrosive, reactive, toxic); hazard communication consistent with the department of transportation requirements at 49 CFR Part 172 subpart E (labeling) or subpart F (placarding); a hazard statement or pictogram consistent with the occupational safety and health administration hazard communication standard at 29 CFR 1910.1200; or a chemical hazard label consistent with the national fire protection association code 704].",
        "kind": "requirement",
        "modality": "must",
        "scope_text": "Governed by paragraph (A) as a condition for satellite accumulation exemption.",
        "scope_quotes": [
          "F001"
        ],
        "modality_quote": "shall",
        "references": [
          "49 CFR Part 172 subpart E",
          "49 CFR Part 172 subpart F",
          "29 CFR 1910.1200",
          "national fire protection association code 704"
        ]
      }
    },
    {
      "unit": "F016:F021",
      "unit_attributes": {
        "statement": "A generator who accumulates either acute hazardous waste listed in rule 3745-51-31 or paragraph (E) of rule 3745-51-33 of the Administrative Code or non-acute hazardous waste in excess of the amounts listed in paragraph (A) of rule 3745-52-15 at or near any point of generation shall, within three consecutive calendar days, either comply with the applicable central accumulation area requirements in paragraph (B) of rule 3745-52-16 or paragraph (A) of rule 3745-52-17 of the Administrative Code, or remove the excess from the satellite accumulation area to a central accumulation area operated in accordance with the applicable requirements in paragraph (B) of rule 3745-52-16 or paragraph (A) of rule 3745-52-17 of the Administrative Code, an on-site permit by rule or permitted treatment, storage, or disposal facility, or an off-site designated facility.",
        "kind": "requirement",
        "modality": "must",
        "scope_text": "Applies when a generator accumulates acute hazardous waste listed in rule 3745-51-31 or paragraph (E) of rule 3745-51-33 or non-acute hazardous waste in excess of the amounts listed in paragraph (A) at or near any point of generation.",
        "scope_quotes": [
          "F016"
        ],
        "modality_quote": "shall",
        "choice_text": "Within three consecutive calendar days, the generator must either (a) comply with central accumulation area requirements, or (b) remove the excess to one of three destinations: (i) a compliant central accumulation area, (ii) an on-site permitted/permit-by-rule facility, or (iii) an off-site designated facility.",
        "choice_quote": "F017:F021",
        "references": [
          "3745-51-31",
          "3745-51-33(E)",
          "3745-52-16(B)",
          "3745-52-17(A)"
        ]
      }
    },
    {
      "unit": "F022",
      "unit_attributes": {
        "statement": "During the three-consecutive-calendar-day period when acute or non-acute hazardous waste is accumulated in excess of the satellite accumulation amounts listed in paragraph (A) of rule 3745-52-15, the generator shall continue to comply with paragraphs (A)(1) to (A)(5) of this rule, and shall mark or label the containers holding the excess accumulation of hazardous waste with the date the excess amount began accumulating.",
        "kind": "requirement",
        "modality": "must",
        "scope_text": "Applies during the three-consecutive-calendar-day period when a generator accumulates hazardous waste in excess of the limits specified in paragraph (A).",
        "scope_quotes": [
          "F016",
          "F022"
        ],
        "modality_quote": "shall",
        "references": [
          "paragraphs (A)(1) to (A)(5)"
        ]
      }
    },
    {
      "unit": "F023",
      "unit_attributes": {
        "statement": "All satellite accumulation areas operated by a small quantity generator shall meet the preparedness and prevention requirements of paragraph (B)(8) of rule 3745-52-16 of the Administrative Code and emergency procedures of paragraph (B)(9) of rule 3745-52-16 of the Administrative Code.",
        "kind": "requirement",
        "modality": "must",
        "scope_text": "Applies to all satellite accumulation areas operated by a small quantity generator.",
        "scope_quotes": [
          "F023"
        ],
        "modality_quote": "shall",
        "references": [
          "3745-52-16(B)(8)",
          "3745-52-16(B)(9)"
        ]
      }
    },
    {
      "unit": "F024",
      "unit_attributes": {
        "statement": "All satellite accumulation areas operated by a large quantity generator shall meet the preparedness, prevention, and emergency procedures in rules 3745-52-250 to 3745-52-265 of the Administrative Code.",
        "kind": "requirement",
        "modality": "must",
        "scope_text": "Applies to all satellite accumulation areas operated by a large quantity generator.",
        "scope_quotes": [
          "F024"
        ],
        "modality_quote": "shall",
        "references": [
          "3745-52-250 to 3745-52-265"
        ]
      }
    },
    {
      "unit": "F026",
      "unit_attributes": {
        "statement": "For dates of non-regulatory government publications, publications of recognized organizations and associations, federal rules, and federal statutory provisions referenced in rule 3745-52-15, see rule 3745-50-11 of the Administrative Code titled 'Incorporated by reference.'",
        "kind": "statement",
        "modality": "not_stated",
        "references": [
          "3745-50-11"
        ]
      }
    }
  ]
}
